-- =================================================================================
-- SCRIPT SQL PARA EL SUPABASE DE CÉSAR (wvbcfwhbilutuhpepeme.supabase.co)
-- Las tablas Productos, Ingresos, Salidas, Personal, Maquinaria y Ordenes_de_Trabajo
-- YA EXISTEN. Este script crea únicamente las tablas nuevas pedidas en el audio.
-- =================================================================================

-- 1. TABLA AUXILIAR PARA EL DASHBOARD (HORAS DE EQUIPO / DRON / TRACTOR)
CREATE TABLE IF NOT EXISTS public."Registro_Horas_Tractor" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Fecha" date DEFAULT CURRENT_DATE,
    "Maquinaria" text,
    "Total_Horas" numeric(10,2) DEFAULT 0,
    "Labor" text,
    "Operador" text,
    "created_at" timestamptz DEFAULT now()
);

-- 2. SECCIÓN SERVICIO DRON: CLIENTES
CREATE TABLE IF NOT EXISTS public."Clientes_Dron" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "nombre" text UNIQUE NOT NULL,
    "ruc_dni" text,
    "telefono" text,
    "zona_sector" text,
    "notas" text,
    "activo" boolean DEFAULT true,
    "created_at" timestamptz DEFAULT now()
);

-- 3. SECCIÓN SERVICIO DRON: CAMPOS Y CULTIVOS DELIMITADOS POR CLIENTE (MAPA + GPS GOOGLE MAPS)
CREATE TABLE IF NOT EXISTS public."Campos_Clientes_Dron" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "cliente_id" bigint REFERENCES public."Clientes_Dron"("id") ON DELETE CASCADE,
    "cliente_nombre" text NOT NULL,
    "nombre_campo" text NOT NULL,
    "cultivo" text NOT NULL,
    "area_ha" numeric(10,2) NOT NULL DEFAULT 0,
    "perimetro_m" numeric(10,2) DEFAULT 0,
    "latitud" numeric(10,6),
    "longitud" numeric(10,6),
    "google_maps_url" text,
    "geojson" text,
    "observaciones" text,
    "created_at" timestamptz DEFAULT now()
);

-- 4. SECCIÓN SERVICIO DRON: REGISTRO DE TRABAJOS Y LIQUIDACIÓN / REPORTES PDF
CREATE TABLE IF NOT EXISTS public."Servicios_Dron" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "cliente_id" bigint REFERENCES public."Clientes_Dron"("id") ON DELETE SET NULL,
    "cliente_nombre" text NOT NULL,
    "campo_id" bigint REFERENCES public."Campos_Clientes_Dron"("id") ON DELETE SET NULL,
    "nombre_campo" text NOT NULL,
    "cultivo" text NOT NULL,
    "fecha_servicio" date NOT NULL DEFAULT CURRENT_DATE,
    "hectareas_aplicadas" numeric(10,2) NOT NULL DEFAULT 0,
    "precio_por_ha_pen" numeric(10,2) NOT NULL DEFAULT 60.0,
    "total_cobrar_pen" numeric(12,2) NOT NULL DEFAULT 0,
    "tipo_aplicacion" text DEFAULT 'Aplicación Agroquímicos Dron',
    "productos_aplicados" text,
    "volumen_caldo_l_ha" numeric(10,2) DEFAULT 25.0,
    "piloto_operador" text DEFAULT 'César',
    "dron_equipo" text DEFAULT 'DJI Agras',
    "estado_pago" text DEFAULT 'Pendiente',
    "monto_pagado_pen" numeric(12,2) DEFAULT 0,
    "observaciones" text,
    "created_at" timestamptz DEFAULT now()
);

-- 5. SECCIÓN CAMPOS PROPIOS: CATASTRO DE LOTES DE CÉSAR
CREATE TABLE IF NOT EXISTS public."Campos_Propios" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "nombre_lote" text UNIQUE NOT NULL,
    "cultivo_actual" text NOT NULL,
    "variedad" text,
    "area_ha" numeric(10,2) NOT NULL DEFAULT 1.0,
    "perimetro_m" numeric(10,2) DEFAULT 0,
    "fecha_siembra" date,
    "fecha_trasplante" date,
    "latitud" numeric(10,6),
    "longitud" numeric(10,6),
    "google_maps_url" text,
    "geojson" text,
    "estado" text DEFAULT 'En Campaña 🟢',
    "observaciones" text,
    "created_at" timestamptz DEFAULT now()
);

-- 6. SECCIÓN CAMPOS PROPIOS: HISTORIAL (FERTILIZANTES, APLICACIONES DRON, EXTRAS/LABORES)
CREATE TABLE IF NOT EXISTS public."Historial_Campos_Propios" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "campo_id" bigint REFERENCES public."Campos_Propios"("id") ON DELETE CASCADE,
    "nombre_lote" text NOT NULL,
    "cultivo" text NOT NULL,
    "categoria" text NOT NULL, -- 'Fertilizantes' | 'Aplicaciones' | 'Extras'
    "fecha" date NOT NULL DEFAULT CURRENT_DATE,
    "etapa_labor" text NOT NULL, -- ej. '1ra Fertilizada', 'Control Insecticida', 'Siembra', 'Trasplante', 'Quema de Hierba'
    "productos_detalle" text, -- ej. 'Urea + Fosfato Diamónico' o 'Semilla certificada'
    "dosis_por_ha" text, -- ej. '150 Kg/ha' o '25 L caldo/ha'
    "cantidad_total" numeric(10,2) DEFAULT 0,
    "unidad" text DEFAULT 'Kg',
    "costo_total_pen" numeric(12,2) DEFAULT 0,
    "metodo_equipo" text DEFAULT 'Manual',
    "alerta_campo" text DEFAULT 'Normal 🟢', -- ej. 'Deficiencia de Agua 💧', 'Presencia de Plaga 🐛', 'Maleza Alta 🌿'
    "observaciones" text,
    "created_at" timestamptz DEFAULT now()
);

-- 7. SECCIÓN MONITOREO MULTIESPECTRAL (NDVI / VIGOR)
CREATE TABLE IF NOT EXISTS public."Monitoreo_Multiespectral" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "tipo_propiedad" text DEFAULT 'Campo Propio', -- 'Campo Propio' | 'Cliente Dron'
    "propietario" text DEFAULT 'César',
    "nombre_campo" text NOT NULL,
    "cultivo" text NOT NULL,
    "fecha_monitoreo" date NOT NULL DEFAULT CURRENT_DATE,
    "indice" text DEFAULT 'NDVI (Vigor Vegetativo)',
    "valor_promedio" numeric(5,3) DEFAULT 0.720,
    "valor_min" numeric(5,3) DEFAULT 0.410,
    "valor_max" numeric(5,3) DEFAULT 0.880,
    "pct_vigor_optimo" numeric(5,2) DEFAULT 75.0,
    "pct_vigor_moderado" numeric(5,2) DEFAULT 18.0,
    "pct_estres_critico" numeric(5,2) DEFAULT 7.0,
    "diagnostico" text,
    "recomendacion_dron" text,
    "latitud" numeric(10,6),
    "longitud" numeric(10,6),
    "geojson" text,
    "created_at" timestamptz DEFAULT now()
);

-- HABILITAR ACCESO RLS PARA LAS NUEVAS TABLAS
ALTER TABLE public."Registro_Horas_Tractor" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."Clientes_Dron" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."Campos_Clientes_Dron" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."Servicios_Dron" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."Campos_Propios" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."Historial_Campos_Propios" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."Monitoreo_Multiespectral" ENABLE ROW LEVEL SECURITY;

DO $$
DECLARE
    t text;
BEGIN
    FOREACH t IN ARRAY ARRAY[
        'Registro_Horas_Tractor', 'Clientes_Dron',
        'Campos_Clientes_Dron', 'Servicios_Dron', 'Campos_Propios',
        'Historial_Campos_Propios', 'Monitoreo_Multiespectral'
    ]
    LOOP
        EXECUTE format('DROP POLICY IF EXISTS "Acceso total %I" ON public.%I', t, t);
        EXECUTE format('CREATE POLICY "Acceso total %I" ON public.%I FOR ALL USING (true) WITH CHECK (true)', t, t);
    END LOOP;
END
$$;
